// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';
import { ndarray } from '@stdlib/types/ndarray';

/**
* Line style.
*/
type LineStyle = '-' | '--' | '-.' | ':';

/**
* Chart data (either an array-like object or an ndarray).
*/
type Data = Collection | ndarray;

/**
* Callback invoked upon rendering a chart.
*
* @param error - error object (or `null` upon success)
* @param svg - rendered SVG string
*/
type RenderCallback = ( error: Error | null, svg?: string ) => void;

/**
* Chart padding.
*/
interface Padding {
	/**
	* Bottom padding (in pixels).
	*/
	bottom?: number;

	/**
	* Left padding (in pixels).
	*/
	left?: number;

	/**
	* Right padding (in pixels).
	*/
	right?: number;

	/**
	* Top padding (in pixels).
	*/
	top?: number;
}

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Background color.
	*/
	background?: string;

	/**
	* Object mapping chart data field names to encoding channels (`x`, `y`, and `z`).
	*/
	channels?: Record<string, string>;

	/**
	* Line colors (default: category10 color scheme).
	*/
	colors?: string | Array<string>;

	/**
	* Chart data.
	*/
	data?: Collection;

	/**
	* Chart description.
	*/
	description?: string;

	/**
	* Chart height (in pixels).
	*/
	height?: number;

	/**
	* Data labels.
	*/
	labels?: Array<string>;

	/**
	* Boolean indicating whether to display a chart legend (default: `false`).
	*/
	legend?: boolean;

	/**
	* Line opacity (default: `[ 1.0 ]`).
	*/
	lineOpacity?: number | Array<number>;

	/**
	* Line style(s) (default: `[ '-' ]`).
	*/
	lineStyle?: LineStyle | Array<LineStyle>;

	/**
	* Legend line symbol(s) (default: `[ 'stroke' ]`).
	*/
	lineSymbol?: string | Array<string>;

	/**
	* Line width(s) in pixels (default: `[ 2 ]`).
	*/
	lineWidth?: number | Array<number>;

	/**
	* Chart padding.
	*/
	padding?: Padding;

	/**
	* Chart theme.
	*/
	theme?: Record<string, any>;

	/**
	* Chart title.
	*/
	title?: string | Array<string>;

	/**
	* Default chart viewer.
	*/
	viewer?: string;

	/**
	* Chart width (in pixels).
	*/
	width?: number;

	/**
	* x-axis tick format.
	*/
	xFormat?: string | Record<string, any>;

	/**
	* Maximum value of the x-axis domain.
	*/
	xMax?: number;

	/**
	* Minimum value of the x-axis domain.
	*/
	xMin?: number;

	/**
	* x-axis scale type.
	*/
	xScaleType?: string;

	/**
	* Number of x-axis tick marks.
	*/
	xTickCount?: number | string | Record<string, any>;

	/**
	* x-axis label.
	*/
	xTitle?: string | Array<string>;

	/**
	* y-axis tick format.
	*/
	yFormat?: string | Record<string, any>;

	/**
	* Maximum value of the y-axis domain.
	*/
	yMax?: number;

	/**
	* Minimum value of the y-axis domain.
	*/
	yMin?: number;

	/**
	* y-axis scale type.
	*/
	yScaleType?: string;

	/**
	* Number of y-axis tick marks.
	*/
	yTickCount?: number | string | Record<string, any>;

	/**
	* y-axis label.
	*/
	yTitle?: string | Array<string>;
}

/**
* Ordinal scale.
*/
interface OrdinalScale {
	/**
	* Scale name.
	*/
	name: string;

	/**
	* Scale domain.
	*/
	domain: any;

	/**
	* Scale range.
	*/
	range: any;
}

/**
* Line chart.
*/
declare class LineChart {
	/**
	* Line chart constructor.
	*
	* @param options - constructor options
	* @param options.background - background color
	* @param options.channels - object mapping chart data field names to encoding channels (`x`, `y`, and `z`)
	* @param options.colors - line colors
	* @param options.data - chart data
	* @param options.description - chart description
	* @param options.height - chart height (in pixels)
	* @param options.labels - data labels
	* @param options.legend - boolean indicating whether to display a chart legend (default: `false`)
	* @param options.lineOpacity - line opacity (default: `[ 1.0 ]`)
	* @param options.lineStyle - line style(s) (default: `[ '-' ]`)
	* @param options.lineSymbol - legend line symbol(s) (default: `[ 'stroke' ]`)
	* @param options.lineWidth - line width(s) in pixels (default: `[ 2 ]`)
	* @param options.padding - chart padding
	* @param options.theme - chart theme
	* @param options.title - chart title
	* @param options.viewer - default chart viewer
	* @param options.width - chart width (in pixels)
	* @param options.xFormat - x-axis tick format
	* @param options.xMax - maximum value of the x-axis domain
	* @param options.xMin - minimum value of the x-axis domain
	* @param options.xScaleType - x-axis scale type
	* @param options.xTickCount - number of x-axis tick marks
	* @param options.xTitle - x-axis label
	* @param options.yFormat - y-axis tick format
	* @param options.yMax - maximum value of the y-axis domain
	* @param options.yMin - minimum value of the y-axis domain
	* @param options.yScaleType - y-axis scale type
	* @param options.yTickCount - number of y-axis tick marks
	* @param options.yTitle - y-axis label
	* @throws must provide valid options
	* @returns line chart instance
	*
	* @example
	* var chart = new LineChart({
	*     'lineStyle': '--',
	*     'legend': true
	* });
	* // returns <LineChart>
	*/
	constructor( options?: Options );

	/**
	* Line chart constructor.
	*
	* @param y - y-values
	* @param options - constructor options
	* @throws must provide valid options
	* @returns line chart instance
	*
	* @example
	* var chart = new LineChart( [ 4, 5, 6 ] );
	* // returns <LineChart>
	*/
	constructor( y: Data | Array<Data>, options?: Options );

	/**
	* Line chart constructor.
	*
	* @param x - x-values
	* @param y - y-values
	* @param options - constructor options
	* @throws must provide valid options
	* @returns line chart instance
	*
	* @example
	* var chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	* // returns <LineChart>
	*/
	constructor( x: Data | Array<Data>, y: Data | Array<Data>, options?: Options );

	/**
	* Line colors.
	*
	* ## Notes
	*
	* -   When set, a string is coerced to an array containing a single color.
	*
	* @example
	* var chart = new LineChart();
	*
	* chart.colors = [ '#000', 'steelblue' ];
	*
	* var v = chart.colors;
	* // returns [ '#000', 'steelblue' ]
	*/
	colors: string | Array<string>;

	/**
	* Ordinal scale mapping datasets to line colors.
	*
	* @example
	* var chart = new LineChart();
	*
	* var v = chart.colorScale;
	* // returns <OrdinalScale>
	*/
	readonly colorScale: OrdinalScale;

	/**
	* Boolean indicating whether to display a chart legend.
	*
	* @example
	* var chart = new LineChart();
	*
	* chart.legend = true;
	*
	* var v = chart.legend;
	* // returns true
	*/
	legend: boolean;

	/**
	* Line opacity.
	*
	* ## Notes
	*
	* -   Each value must be on the interval `[0,1]`.
	* -   When set, a number is coerced to an array containing a single opacity.
	*
	* @example
	* var chart = new LineChart();
	*
	* chart.lineOpacity = [ 1.0, 0.5 ];
	*
	* var v = chart.lineOpacity;
	* // returns [ 1.0, 0.5 ]
	*/
	lineOpacity: number | Array<number>;

	/**
	* Ordinal scale mapping datasets to line opacities.
	*
	* @example
	* var chart = new LineChart();
	*
	* var v = chart.lineOpacityScale;
	* // returns <OrdinalScale>
	*/
	readonly lineOpacityScale: OrdinalScale;

	/**
	* Line style(s).
	*
	* ## Notes
	*
	* -   When set, a string is coerced to an array containing a single line style.
	*
	* @example
	* var chart = new LineChart();
	*
	* chart.lineStyle = [ '-', '--' ];
	*
	* var v = chart.lineStyle;
	* // returns [ '-', '--' ]
	*/
	lineStyle: LineStyle | Array<LineStyle>;

	/**
	* Ordinal scale mapping datasets to line styles (as SVG dash arrays).
	*
	* @example
	* var chart = new LineChart();
	*
	* var v = chart.lineStyleScale;
	* // returns <OrdinalScale>
	*/
	readonly lineStyleScale: OrdinalScale;

	/**
	* Legend line symbol(s).
	*
	* ## Notes
	*
	* -   When set, a string is coerced to an array containing a single symbol.
	*
	* @example
	* var chart = new LineChart();
	*
	* chart.lineSymbol = [ 'stroke', 'circle' ];
	*
	* var v = chart.lineSymbol;
	* // returns [ 'stroke', 'circle' ]
	*/
	lineSymbol: string | Array<string>;

	/**
	* Ordinal scale mapping datasets to legend line symbols.
	*
	* @example
	* var chart = new LineChart();
	*
	* var v = chart.lineSymbolScale;
	* // returns <OrdinalScale>
	*/
	readonly lineSymbolScale: OrdinalScale;

	/**
	* Line width(s) in pixels.
	*
	* ## Notes
	*
	* -   When set, a number is coerced to an array containing a single line width.
	*
	* @example
	* var chart = new LineChart();
	*
	* chart.lineWidth = [ 2, 4 ];
	*
	* var v = chart.lineWidth;
	* // returns [ 2, 4 ]
	*/
	lineWidth: number | Array<number>;

	/**
	* Ordinal scale mapping datasets to line widths.
	*
	* @example
	* var chart = new LineChart();
	*
	* var v = chart.lineWidthScale;
	* // returns <OrdinalScale>
	*/
	readonly lineWidthScale: OrdinalScale;

	/**
	* Renders a chart as an SVG string.
	*
	* @param clbk - callback to invoke after rendering the chart
	* @throws must provide a function
	*
	* @example
	* var chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	*
	* chart.render( onRender );
	*
	* function onRender( error, svg ) {
	*     if ( error ) {
	*         throw error;
	*     }
	*     // ...
	* }
	*/
	render( clbk: RenderCallback ): void;

	/**
	* Serializes a chart as a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @returns JSON object
	*
	* @example
	* var chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	*
	* var v = chart.toJSON();
	* // returns {...}
	*/
	toJSON(): any;

	/**
	* Adds an event listener.
	*
	* @param event - event name
	* @param listener - event listener
	* @returns chart instance
	*/
	on( event: string, listener: ( ...args: Array<any> ) => void ): this;

	/**
	* Removes an event listener.
	*
	* @param event - event name
	* @param listener - event listener
	* @returns chart instance
	*/
	removeListener( event: string, listener: ( ...args: Array<any> ) => void ): this;
}


// EXPORTS //

export = LineChart;
